70			g_free(server->nick);
71			server->nick = g_strdup(nick);
72		}
73	
74		/* set the server address */
75		g_free(server->real_address);
76		server->real_address = from == NULL ?
77			g_strdup(server->connrec->address) : /* shouldn't happen.. */
78			g_strdup(from);
79	
80		/* last welcome message found - commands can be sent to server now. */
81		server->connected = 1;
82		server->real_connect_time = time(NULL);
83	
84		/* let the queue send now that we are identified */
85		g_get_current_time(&server->wait_cmd);
86	
87		if (server->connrec->usermode != NULL) {
88			/* Send the user mode, before the autosendcmd.
89			 * Do not pass this through cmd_mode because it
90			 * is not known whether the resulting MODE message
91			 * (if any) is the initial umode or a reply to this.
92			 */
93			irc_send_cmdv(server, "MODE %s %s", server->nick,
94					server->connrec->usermode);
95			g_free_not_null(server->wanted_usermode);
96			server->wanted_usermode = g_strdup(server->connrec->usermode);
97		}
98	
99		signal_emit("event connected", 1, server);
100		g_free(params);
101	}
