47	/* The core of the irc_send_cmd* functions. If `raw' is TRUE, the `cmd'
48	   won't be checked at all if it's 512 bytes or not, or if it contains
49	   line feeds or not. Use with extreme caution! */
50	void irc_send_cmd_full(IRC_SERVER_REC *server, const char *cmd,
51			       int send_now, int immediate, int raw)
52	{
53		GString *str;
54		int len;
55		gboolean server_supports_tag;
56	
57		g_return_if_fail(server != NULL);
58		g_return_if_fail(cmd != NULL);
59	
60		if (server->connection_lost)
61			return;
62	
63		str = g_string_sized_new(MAX_IRC_USER_TAGS_LEN + 2 /* `@'+SPACE */ +
64					 server->max_message_len + 2 /* CR+LF */ + 1 /* `\0' */);
65	
66		if (server->cmdcount == 0)
67			irc_servers_start_cmd_timeout();
68		server->cmdcount++;
69	
70		if (!raw) {
71			const char *tmp = cmd;
72	
73			server_supports_tag = server->cap_supported != NULL &&
74				g_hash_table_lookup_extended(server->cap_supported, CAP_MESSAGE_TAGS, NULL, NULL);
75	
76			if (*cmd == '@' && server_supports_tag) {
77				const char *end;
78	
79				while (*tmp != ' ' && *tmp != '\0')
80					tmp++;
81	
82				end = tmp;
83	
84				if (tmp - cmd > MAX_IRC_USER_TAGS_LEN) {
85					g_warning("irc_send_cmd_full(); tags too long(%ld)", tmp - cmd);
86					while (tmp - cmd > MAX_IRC_USER_TAGS_LEN && cmd != tmp - 1) tmp--;
87					while (*tmp != ',' && cmd != tmp - 1) tmp--;
88				}
89				if (cmd != tmp)
90					g_string_append_len(str, cmd, tmp - cmd);
91	
92				tmp = end;
93				while (*tmp == ' ') tmp++;
94	
95				if (*tmp != '\0' && str->len > 0)
96					g_string_append_c(str, ' ');
97			}
98			len = strlen(tmp);
99	
100			/* check that we don't send any longer commands
101			   than 510 bytes (2 bytes for CR+LF) */
102			g_string_append_len(str, tmp, len > server->max_message_len ?
103					    server->max_message_len : len);
104		} else {
105			g_string_append(str, cmd);
106		}
107	
108		if (send_now) {
109			rawlog_output(server->rawlog, str->str);
110			server_redirect_command(server, str->str, server->redirect_next);
111	                server->redirect_next = NULL;
112		}
113	
114		if (!raw) {
115	                /* Add CR+LF to command */
116			g_string_append_c(str, 13);
117			g_string_append_c(str, 10);
118		}
119	
120		if (send_now) {
121	                irc_server_send_data(server, str->str, str->len);
122			g_string_free(str, TRUE);
123		} else {
124	
125			/* add to queue */
126			if (immediate) {
127				server->cmdqueue = g_slist_prepend(server->cmdqueue,
128								   server->redirect_next);
129				server->cmdqueue = g_slist_prepend(server->cmdqueue,
130								   g_string_free(str, FALSE));
131			} else {
132				server->cmdqueue = g_slist_append(server->cmdqueue,
133								  g_string_free(str, FALSE));
134				server->cmdqueue = g_slist_append(server->cmdqueue,
135								  server->redirect_next);
136			}
137		}
138	        server->redirect_next = NULL;
139	}
