226	void irc_send_cmd_split(IRC_SERVER_REC *server, const char *cmd,
227				int nickarg, int max_nicks)
228	{
229		char *str, *pre, *post, *nicks;
230		char **nicklist, **tmp;
231		GString *nickstr;
232		int count;
233	
234		g_return_if_fail(server != NULL);
235		g_return_if_fail(cmd != NULL);
236	
237		str = split_nicks(cmd, &pre, &nicks, &post, nickarg);
238		if (nicks == NULL) {
239	                /* no nicks given? */
240			g_free(str);
241			return;
242		}
243	
244		/* split the nicks */
245		nickstr = g_string_new(NULL);
246		nicklist = g_strsplit(nicks, ",", -1); count = 0;
247	
248		tmp = nicklist;
249		for (;; tmp++) {
250			if (*tmp != NULL) {
251				g_string_append_printf(nickstr, "%s,", *tmp);
252				if (++count < max_nicks)
253					continue;
254			}
255	
256			count = 0;
257			if (nickstr->len > 0)
258				g_string_truncate(nickstr, nickstr->len-1);
259	
260			if (post == NULL)
261				irc_send_cmdv(server, "%s %s", pre, nickstr->str);
262			else
263				irc_send_cmdv(server, "%s %s %s", pre, nickstr->str, post);
264	
265			g_string_truncate(nickstr, 0);
266	
267			if (*tmp == NULL || tmp[1] == NULL)
268				break;
269		}
270		g_strfreev(nicklist);
271		g_string_free(nickstr, TRUE);
272	
273		g_free(str);
274	}
