329	/* Given a string containing <params>, strip any colon prefixing <trailing>. */
330	static void strip_params_colon(char *const params)
331	{
332		char *s;
333	
334		if (params == NULL) {
335			return;
336		}
337	
338		s = params;
339		while (*s != '\0') {
340			if (*s == ':') {
341				memmove(s, s+1, strlen(s+1)+1);
342				return;
343			}
344	
345			s = strchr(s, ' ');
346			if (s == NULL) {
347				return;
348			}
349	
350			while (*s == ' ') {
351				s++;
352			}
353		}
354	}
