356	static void irc_server_event(IRC_SERVER_REC *server, const char *line,
357				     const char *nick, const char *address)
358	{
359	        const char *signal;
360		char *event, *args;
361	
362		g_return_if_fail(line != NULL);
363	
364		/* split event / args */
365		event = g_strconcat("event ", line, NULL);
366		args = strchr(event+6, ' ');
367		if (args != NULL) *args++ = '\0'; else args = "";
368		while (*args == ' ') args++;
369		ascii_strdown(event);
370	
371	        /* check if event needs to be redirected */
372		signal = server_redirect_get_signal(server, nick, event, args);
373		if (signal == NULL)
374			signal = event;
375	        else
376			rawlog_redirect(server->rawlog, signal);
377	
378	        /* emit it */
379		current_server_event = event+6;
380		if (!signal_emit(signal, 4, server, args, nick, address))
381			signal_emit_id(signal_default_event, 4, server, line, nick, address);
382		current_server_event = NULL;
