448	static void irc_server_event_tags(IRC_SERVER_REC *server, const char *line, const char *nick,
449	                                  const char *address, const char *tags)
450	{
451		char *timestr;
452		GHashTable *tags_hash = NULL;
453	
454		if (tags != NULL && *tags != '\0') {
455			tags_hash = irc_parse_message_tags(tags);
456			if ((timestr = g_hash_table_lookup(tags_hash, "time")) != NULL) {
457				server_meta_stash(SERVER(server), "time", timestr);
458			}
459		}
460	
461		if (*line != '\0')
462			signal_emit_id(signal_server_event, 4, server, line, nick, address);
463	
464		if (tags_hash != NULL)
465			g_hash_table_destroy(tags_hash);
