516	/* Parse command line sent by server */
517	static void irc_parse_incoming_line(IRC_SERVER_REC *server, char *line)
518	{
519		char *nick, *address, *tags;
520	
521		g_return_if_fail(server != NULL);
522		g_return_if_fail(line != NULL);
523	
524		line = irc_parse_prefix(line, &nick, &address, &tags);
525		if (*line != '\0' || tags != NULL)
526			signal_emit_id(signal_server_event_tags, 5, server, line, nick, address, tags);
527	
528		server_meta_clear_all(SERVER(server));
529	}
