252				if (++count < max_nicks)
253					continue;
254			}
255	
256			count = 0;
257			if (nickstr->len > 0)
258				g_string_truncate(nickstr, nickstr->len-1);
259	
260			if (post == NULL)
261				irc_send_cmdv(server, "%s %s", pre, nickstr->str);
262			else
263				irc_send_cmdv(server, "%s %s %s", pre, nickstr->str, post);
264	
265			g_string_truncate(nickstr, 0);
266	
267			if (*tmp == NULL || tmp[1] == NULL)
268				break;
269		}
270		g_strfreev(nicklist);
271		g_string_free(nickstr, TRUE);
272	
273		g_free(str);
274	}
275	
276	/* Get next parameter */
277	char *event_get_param(char **data)
278	{
279		char *pos;
280	
281		g_return_val_if_fail(data != NULL, NULL);
282		g_return_val_if_fail(*data != NULL, NULL);
283	
284		if (**data == ':') {
285			/* last parameter */
286			pos = *data;
287			*data += strlen(*data);
288			return pos+1;
289		}
290	
291		pos = *data;
292		while (**data != '\0' && **data != ' ') (*data)++;
293		if (**data == ' ') *(*data)++ = '\0';
294	
295		return pos;
296	}
297	
298	/* Get count parameters from data */
299	char *event_get_params(const char *data, int count, ...)
300	{
301		char **str, *tmp, *duprec, *datad;
302		gboolean rest;
303		va_list args;
304	
305		g_return_val_if_fail(data != NULL, NULL);
306	
307		va_start(args, count);
308		duprec = datad = g_strdup(data);
309	
310		rest = count & PARAM_FLAG_GETREST;
311		count = PARAM_WITHOUT_FLAGS(count);
312	
313		while (count-- > 0) {
314			str = (char **) va_arg(args, char **);
315			if (count == 0 && rest) {
316				/* Put the rest into the last parameter. */
317				strip_params_colon(datad);
318				tmp = datad;
319			} else {
320				tmp = event_get_param(&datad);
321			}
322			if (str != NULL) *str = tmp;
323		}
324		va_end(args);
325	
326		return duprec;
327	}
328	
329	/* Given a string containing <params>, strip any colon prefixing <trailing>. */
330	static void strip_params_colon(char *const params)
331	{
332		char *s;
333	
334		if (params == NULL) {
335			return;
336		}
337	
338		s = params;
339		while (*s != '\0') {
340			if (*s == ':') {
341				memmove(s, s+1, strlen(s+1)+1);
342				return;
343			}
344	
345			s = strchr(s, ' ');
346			if (s == NULL) {
347				return;
348			}
349	
350			while (*s == ' ') {
351				s++;
352			}
353		}
354	}
355	
356	static void irc_server_event(IRC_SERVER_REC *server, const char *line,
357				     const char *nick, const char *address)
358	{
359	        const char *signal;
360		char *event, *args;
361	
362		g_return_if_fail(line != NULL);
363	
364		/* split event / args */
365		event = g_strconcat("event ", line, NULL);
366		args = strchr(event+6, ' ');
367		if (args != NULL) *args++ = '\0'; else args = "";
368		while (*args == ' ') args++;
369		ascii_strdown(event);
370	
371	        /* check if event needs to be redirected */
372		signal = server_redirect_get_signal(server, nick, event, args);
373		if (signal == NULL)
374			signal = event;
375	        else
376			rawlog_redirect(server->rawlog, signal);
377	
378	        /* emit it */
379		current_server_event = event+6;
380		if (!signal_emit(signal, 4, server, args, nick, address))
381			signal_emit_id(signal_default_event, 4, server, line, nick, address);
382		current_server_event = NULL;
383	
384		g_free(event);
385	}
386	
387	static void unescape_tag(char *tag)
388	{
389		char *tmp;
390	
391		if (tag == NULL)
392			return;
393	
394		tmp = tag;
395		for (; *tmp != '\0'; tmp++, tag++) {
396			if (*tmp == '\\') {
397				tmp++;
398				switch (*tmp) {
399				case ':':
400					*tag = ';';
401					break;
402				case 'n':
403					*tag = '\n';
404					break;
405				case 'r':
406					*tag = '\r';
407					break;
408				case 's':
409					*tag = ' ';
410					break;
411				default:
412					*tag = *tmp;
413					break;
414				}
415			} else {
416				*tag = *tmp;
417			}
418		}
419		*tag = '\0';
420	}
421	
422	static gboolean i_str0_equal(const char *s1, const char *s2)
423	{
424		return g_strcmp0(s1, s2) == 0;
425	}
426	
427	GHashTable *irc_parse_message_tags(const char *tags)
428	{
429		char **split, **tmp, **kv;
430		GHashTable *hash;
431	
432		hash = g_hash_table_new_full(g_str_hash, (GEqualFunc) i_str0_equal,
433		                             (GDestroyNotify) i_refstr_release, (GDestroyNotify) g_free);
434		split = g_strsplit(tags, ";", -1);
435		for (tmp = split; *tmp != NULL; tmp++) {
436			if (*tmp[0] == '\0')
437				continue;
438			kv = g_strsplit(*tmp, "=", 2);
439			unescape_tag(kv[1]);
440			g_hash_table_replace(hash, i_refstr_intern(kv[0]),
441			                     g_strdup(kv[1] == NULL ? "" : kv[1]));
442			g_strfreev(kv);
443		}
444		g_strfreev(split);
445		return hash;
446	}
447	
448	static void irc_server_event_tags(IRC_SERVER_REC *server, const char *line, const char *nick,
449	                                  const char *address, const char *tags)
450	{
451		char *timestr;
452		GHashTable *tags_hash = NULL;
453	
454		if (tags != NULL && *tags != '\0') {
455			tags_hash = irc_parse_message_tags(tags);
456			if ((timestr = g_hash_table_lookup(tags_hash, "time")) != NULL) {
457				server_meta_stash(SERVER(server), "time", timestr);
458			}
459		}
460	
461		if (*line != '\0')
462			signal_emit_id(signal_server_event, 4, server, line, nick, address);
463	
464		if (tags_hash != NULL)
465			g_hash_table_destroy(tags_hash);
466	}
467	
468	static char *irc_parse_prefix(char *line, char **nick, char **address, char **tags)
469	{
470		char *p;
471	
472		*nick = *address = *tags = NULL;
473	
474		/* ["@" <tags> SPACE] :<nick> [["!" <user>] "@" <host>] SPACE */
475	
476		if (*line == '@') {
477			*tags = ++line;
478			while (*line != '\0' && *line != ' ') {
479				line++;
480			}
481			if (*line == ' ') {
482				*line++ = '\0';
483				while (*line == ' ') line++;
484			}
485		}
486	
487		if (*line != ':')
488			return line;
489	
490		*nick = ++line; p = NULL;
491		while (*line != '\0' && *line != ' ') {
492			if (*line == '!' || *line == '@') {
493				p = line;
494				if (*line == '!')
495					break;
496			}
497			line++;
498		}
499	
500		if (p != NULL) {
501			line = p;
502			*line++ = '\0';
503			*address = line;
504			while (*line != '\0' && *line != ' ')
505				line++;
506		}
507	
508		if (*line == ' ') {
509			*line++ = '\0';
510			while (*line == ' ') line++;
511		}
512	
513		return line;
514	}
515	
516	/* Parse command line sent by server */
517	static void irc_parse_incoming_line(IRC_SERVER_REC *server, char *line)
518	{
519		char *nick, *address, *tags;
520	
521		g_return_if_fail(server != NULL);
522		g_return_if_fail(line != NULL);
523	
524		line = irc_parse_prefix(line, &nick, &address, &tags);
525		if (*line != '\0' || tags != NULL)
526			signal_emit_id(signal_server_event_tags, 5, server, line, nick, address, tags);
527	
528		server_meta_clear_all(SERVER(server));
529	}
530	
531	/* input function: handle incoming server messages */
532	static void irc_parse_incoming(SERVER_REC *server)
533	{
534		char *str;
535		int count;
536		int ret;
537	
538		g_return_if_fail(server != NULL);
539	
540		/* Some commands can send huge replies and irssi might handle them
541		   too slowly, so read only a few times from the socket before
542		   letting other tasks to run. */
543		count = 0;
544		ret = 0;
545		server_ref(server);
546		while (!server->disconnected &&
547		       (ret = net_sendbuffer_receive_line(server->handle, &str, count < MAX_SOCKET_READS)) > 0) {
548			rawlog_input(server->rawlog, str);
549			signal_emit_id(signal_server_incoming, 2, server, str);
550	
551			if (server->connection_lost)
552				server_disconnect(server);
553	
554			count++;
555		}
556		if (ret == -1) {
557			/* connection lost */
558			server->connection_lost = TRUE;
559			server_disconnect(server);
560		}
561		server_unref(server);
562	}
563	
564	static void irc_init_server(IRC_SERVER_REC *server)
565	{
566		g_return_if_fail(server != NULL);
567	
568		if (!IS_IRC_SERVER(server))
569			return;
570	
571		server->readtag = i_input_add(net_sendbuffer_handle(server->handle), I_INPUT_READ,
572		                              (GInputFunction) irc_parse_incoming, server);
573	}
574	
575	void irc_irc_init(void)
576	{
577		signal_add("server event", (SIGNAL_FUNC) irc_server_event);
578		signal_add("server event tags", (SIGNAL_FUNC) irc_server_event_tags);
579		signal_add("server connected", (SIGNAL_FUNC) irc_init_server);
580		signal_add("server incoming", (SIGNAL_FUNC) irc_parse_incoming_line);
581	
582		current_server_event = NULL;
583		signal_default_event = signal_get_uniq_id("default event");
584		signal_server_event = signal_get_uniq_id("server event");
585		signal_server_event_tags = signal_get_uniq_id("server event tags");
586		signal_server_incoming = signal_get_uniq_id("server incoming");
587	}
588	
589	void irc_irc_deinit(void)
590	{
591		signal_remove("server event", (SIGNAL_FUNC) irc_server_event);
592		signal_remove("server event tags", (SIGNAL_FUNC) irc_server_event_tags);
593		signal_remove("server connected", (SIGNAL_FUNC) irc_init_server);
594		signal_remove("server incoming", (SIGNAL_FUNC) irc_parse_incoming_line);
595	}
