491		if (!server_ischannel(SERVER(server), channel)) {
492			/* user mode change */
493			parse_user_mode(server, mode);
494		} else {
495			/* channel mode change */
496			chanrec = irc_channel_find(server, channel);
497			if (chanrec != NULL)
498				parse_channel_modes(chanrec, nick, mode, TRUE);
499		}
500	
501		g_free(params);
502	}
