551	void channel_set_singlemode(IRC_CHANNEL_REC *channel, const char *nicks,
552				    const char *mode)
553	{
554		GString *str;
555		int num, modepos;
556		char **nick, **nicklist;
557	
558		g_return_if_fail(IS_IRC_CHANNEL(channel));
559		g_return_if_fail(nicks != NULL && mode != NULL);
560		if (*nicks == '\0') return;
561	
562		num = modepos = 0;
563		str = g_string_new(NULL);
564	
565		nicklist = g_strsplit(nicks, " ", -1);
566		for (nick = nicklist; *nick != NULL; nick++) {
567			if (**nick == '\0')
568				continue;
569	
570			if (num == 0)
571			{
572				g_string_printf(str, "MODE %s %s",
573						 channel->name, mode);
574				modepos = str->len;
575			} else {
576				/* insert the mode string */
577				g_string_insert(str, modepos, mode);
578			}
579	
580			g_string_append_printf(str, " %s", *nick);
581	
582			if (++num == channel->server->max_modes_in_cmd) {
583				/* max. modes / command reached, send to server */
584				irc_send_cmd(channel->server, str->str);
585				num = 0;
586			}
587		}
588		if (num > 0) irc_send_cmd(channel->server, str->str);
589	
590		g_strfreev(nicklist);
591		g_string_free(str, TRUE);
592	}
593	
594	void channel_set_mode(IRC_SERVER_REC *server, const char *channel,
595			      const char *mode)
596	{
597		IRC_CHANNEL_REC *chanrec;
598		GString *tmode, *targs;
599		char *modestr, *curmode, *orig, type, prevtype;
600		int count;
601	
602		g_return_if_fail(IS_IRC_SERVER(server));
603		g_return_if_fail(channel != NULL && mode != NULL);
604	
605		tmode = g_string_new(NULL);
606		targs = g_string_new(NULL);
607		count = 0;
608	
609		chanrec = irc_channel_find(server, channel);
610		if (chanrec != NULL)
611			channel = chanrec->name;
612	
613		orig = modestr = g_strdup(mode);
614	
615	        type = '+'; prevtype = '\0';
616		curmode = cmd_get_param(&modestr);
617		for (;; curmode++) {
618			if (*curmode == '\0') {
619				/* support for +o nick +o nick2 */
620				curmode = cmd_get_param(&modestr);
621				if (*curmode == '\0')
622					break;
623			}
624	
625			if (*curmode == '+' || *curmode == '-') {
626				type = *curmode;
627				continue;
628			}
629	
630			if (count == server->max_modes_in_cmd &&
631			    HAS_MODE_ARG(server, type, *curmode)) {
632				irc_send_cmdv(server, "MODE %s %s%s",
633					      channel, tmode->str, targs->str);
634	
635				count = 0; prevtype = '\0';
636				g_string_truncate(tmode, 0);
637				g_string_truncate(targs, 0);
638			}
639	
640			if (type != prevtype) {
641				prevtype = type;
642				g_string_append_c(tmode, type);
643			}
644			g_string_append_c(tmode, *curmode);
645	
646			if (HAS_MODE_ARG(server, type, *curmode)) {
647				char *arg;
648	
649				count++;
650				arg = cmd_get_param(&modestr);
651				if (*arg == '\0' && type == '-' && *curmode == 'k') {
652					/* "/mode #channel -k" - no reason why it
653					   shouldn't work really, so append the key */
654					IRC_CHANNEL_REC *chanrec;
655	
656					chanrec = irc_channel_find(server, channel);
657					if (chanrec != NULL && chanrec->key != NULL)
658	                                        arg = chanrec->key;
659				}
660	
661				if (*arg != '\0')
662					g_string_append_printf(targs, " %s", arg);
663			}
664		}
665	
666		if (tmode->len > 0) {
667			irc_send_cmdv(server, "MODE %s %s%s",
668				      channel, tmode->str, targs->str);
669		}
670	
671		g_string_free(tmode, TRUE);
672		g_string_free(targs, TRUE);
673		g_free(orig);
674	}
