676	static int get_wildcard_nicks(GString *output, const char *mask,
677				      IRC_CHANNEL_REC *channel, int op, int voice)
678	{
679		GSList *nicks, *tmp;
680	        int count;
681	
682		g_return_val_if_fail(output != NULL, 0);
683		g_return_val_if_fail(mask != NULL, 0);
684		g_return_val_if_fail(IS_IRC_CHANNEL(channel), 0);
685	
686	        count = 0;
687		nicks = nicklist_find_multiple(CHANNEL(channel), mask);
688		for (tmp = nicks; tmp != NULL; tmp = tmp->next) {
689			NICK_REC *rec = tmp->data;
690	
691			if ((op == 1 && !rec->op) || (op == 0 && rec->op) ||
692			    (voice == 1 && !rec->voice) || (voice == 0 && rec->voice))
693				continue;
694	
695			if (g_ascii_strcasecmp(rec->nick, channel->server->nick) == 0)
696				continue;
697	
698			g_string_append_printf(output, "%s ", rec->nick);
699	                count++;
700		}
701		g_slist_free(nicks);
702	
703	        return count;
704	}
705	
706	static char *get_nicks(IRC_SERVER_REC *server, WI_ITEM_REC *item,
707			       const char *data, int op, int voice,
708			       IRC_CHANNEL_REC **ret_channel)
709	{
710	        IRC_CHANNEL_REC *channel;
711	        GString *str;
712	        GHashTable *optlist;
713		char **matches, **match, *ret, *channame, *nicks;
714		void *free_arg;
715	        int count, max_modes;
716	
717		if (!cmd_get_params(data, &free_arg, 2 | PARAM_FLAG_GETREST |
718				    PARAM_FLAG_OPTIONS | PARAM_FLAG_OPTCHAN_NAME,
719				    item, "op", &optlist, &channame, &nicks))
720			return NULL;
721	
722		if (*nicks == '\0')
723			return NULL;
724	
725		channel = irc_channel_find(server, channame);
726		if (channel == NULL) {
727			cmd_params_free(free_arg);
728			return NULL;
729		}
730	
731		str = g_string_new(NULL);
732		matches = g_strsplit(nicks, " ", -1);
733		for (match = matches; *match != NULL; match++) {
734			if (strchr(*match, '*') == NULL &&
735			    strchr(*match, '?') == NULL) {
736				/* no wildcards */
737	                        g_string_append_printf(str, "%s ", *match);
738			} else {
739				count = get_wildcard_nicks(str, *match, channel,
740							   op, voice);
741	                        max_modes = settings_get_int("max_wildcard_modes");
742				if (max_modes > 0 && count > max_modes &&
743				    g_hash_table_lookup(optlist, "yes") == NULL) {
744	                                /* too many matches */
745					g_string_free(str, TRUE);
746					g_strfreev(matches);
747					cmd_params_free(free_arg);
748	
749					signal_emit("error command", 1,
750						    GINT_TO_POINTER(CMDERR_NOT_GOOD_IDEA));
751					signal_stop();
752	                                return NULL;
753				}
754			}
755		}
756	
757	        if (str->len > 0) g_string_truncate(str, str->len-1);
758		ret = str->str;
759		g_string_free(str, FALSE);
760		g_strfreev(matches);
761		cmd_params_free(free_arg);
762	
763		*ret_channel = channel;
764		return ret;
765	}
