41		g_return_if_fail(nick != NULL);
42	
43		nickrec = nicklist_find(CHANNEL(channel), nick);
44		if (nickrec == NULL) return; /* No /names list got yet */
45	
46		if (mode == '@') nickrec->op = type == '+';
47		else if (mode == '+') nickrec->voice = type == '+';
48		else if (mode == '%') nickrec->halfop = type == '+';
49		if (channel->server->prefix[(unsigned char) mode] != '\0') {
50			if (type == '+')
51				prefix_add(nickrec->prefixes, mode, (SERVER_REC *) channel->server);
52			else
53				prefix_del(nickrec->prefixes, mode);
54		}
55	
56		modestr[0] = mode; modestr[1] = '\0';
57		typestr[0] = type; typestr[1] = '\0';
58		signal_emit("nick mode changed", 5,
59			    channel, nickrec, setby, modestr, typestr);
60	}
61	
62	void prefix_add(char prefixes[MAX_USER_PREFIXES+1], char newprefix, SERVER_REC *server)
63	{
64		const char *prefixlst;
65		char newprefixes[MAX_USER_PREFIXES+1]; /* to hold the new prefixes */
66		unsigned int newpos = 0; /* to hold our position in the new prefixes */
67		unsigned int oldpos = 0; /* to hold our position in the old prefixes */
68	
69		prefixlst = server->get_nick_flags(server);
70	
71		/* go through the possible prefixes, copy higher ones, and find this one's place
72		 * always leave room for the current prefix to be added, though.
73		 */
74		while (*prefixlst != '\0' && prefixes[oldpos] != '\0' &&
75				newpos < MAX_USER_PREFIXES - 1) {
76			if (prefixes[oldpos] == newprefix)
77				return; /* already inserted.  why are we here? */
78	
79			if (*prefixlst == newprefix)
80				break; /* insert the new prefix here */
81	
82			if (*prefixlst == prefixes[oldpos]) {
83				/* this prefix is present.
84				 * the one we are inserting goes after it.
85				 * copy it over, and continue searching.
86				 */
87				newprefixes[newpos++] = prefixes[oldpos++];
88			}
89			prefixlst++;
90		}
91	
92		/* newpos is now the position in which we wish to insert the prefix */
93		newprefixes[newpos++] = newprefix;
94	
95		/* finish copying the remaining prefixes */
96		while (prefixes[oldpos] != '\0' && newpos < MAX_USER_PREFIXES)
97			newprefixes[newpos++] = prefixes[oldpos++];
98	
99		newprefixes[newpos] = '\0';
100	
101		strcpy(prefixes, newprefixes);
102	}
103	
104	void prefix_del(char prefixes[MAX_USER_PREFIXES+1], char oldprefix)
105	{
106		char *todel;
107	
108		todel = strchr(prefixes, oldprefix);
109		if (todel)
110			memmove(todel, todel+1, strlen(todel));
111	}
