113	static int mode_is_set(const char *str, char mode)
114	{
115		char *end, *pos;
116	
117		g_return_val_if_fail(str != NULL, FALSE);
118	
119		end = strchr(str, ' ');
120		pos = strchr(str, mode);
121		return pos != NULL && (end == NULL || pos < end);
122	}
123	
124	/* add argument to specified position */
125	static void mode_add_arg(GString *str, int pos, int updating, const char *arg)
126	{
127		char *p;
128	
129		for (p = str->str; *p != '\0'; p++) {
130			if (*p != ' ')
131				continue;
132	
133			if (pos == 0)
134				break;
135			pos--;
136		}
137	
138		pos = (int) (p-str->str);
139		if (updating && *p != '\0') {
140			/* remove the old argument */
141	                p++;
142			while (*p != '\0' && *p != ' ') p++;
143	                g_string_erase(str, pos, (int) (p-str->str)-pos);
144		}
145	
146		g_string_insert_c(str, pos, ' ');
147		g_string_insert(str, pos+1, arg);
148	}
149	
150	/* Add mode character to list sorted alphabetically */
151	static void mode_add_sorted(IRC_SERVER_REC *server, GString *str,
152				    char mode, const char *arg, int user)
153	{
154		char *p;
155		int updating, argpos = 0;
156	
157		/* check that mode isn't already set */
158		if ((!user && !HAS_MODE_ARG_SET(server, mode)) &&
159		    mode_is_set(str->str, mode))
160			return;
161	
162		updating = FALSE;
163		for (p = str->str; *p != '\0' && *p != ' '; p++) {
164			if (mode < *p)
165				break;
166			if (mode == *p) {
167	                        updating = TRUE;
168				break;
169			}
170			if (!user && HAS_MODE_ARG_SET(server, *p))
171				argpos++;
172		}
173	
174		/* .. GLib shouldn't fail when inserting at the end of the string */
175		if (!updating) {
176			if (*p == '\0')
177				g_string_append_c(str, mode);
178			else
179				g_string_insert_c(str, (int) (p-str->str), mode);
180		}
181		if (arg != NULL)
182	                mode_add_arg(str, argpos, updating, arg);
183	}
184	
185	/* remove the n'th argument */
186	static void node_remove_arg(GString *str, int pos)
187	{
188		char *p;
189		int startpos;
190	
191		startpos = -1;
192		for (p = str->str; *p != '\0'; p++) {
193			if (*p != ' ')
194				continue;
195	
196			if (pos < 0)
197				break;
198			if (pos == 0)
199				startpos = (int) (p-str->str);
200			pos--;
201		}
202	
203		if (startpos == -1)
204			return; /* not found */
205	
206	        g_string_erase(str, startpos, (int) (p-str->str)-startpos);
207	}
208	
209	/* remove mode (and it's argument) from string */
210	static void mode_remove(IRC_SERVER_REC *server, GString *str, char mode, int user)
211	{
212		char *p;
213		int argpos = 0;
214	
215		for (p = str->str; *p != '\0' && *p != ' '; p++) {
216			if (mode == *p) {
217				g_string_erase(str, (int) (p-str->str), 1);
218				if (!user && HAS_MODE_ARG_SET(server, mode))
219	                                node_remove_arg(str, argpos);
220				break;
221			}
222			if (!user && HAS_MODE_ARG_SET(server, *p))
223				argpos++;
224		}
225	}
