310				while (*prefix != ')' && *prefix != '\0') {
311					if (*prefix == mode) {
312						channel->chanop = type == '+';
313						break;
314					}
315					if (*prefix == 'o')
316						break;
317					prefix++;
318				}
319			} else {
320				if (mode == 'o' || mode == 'O')
321					channel->chanop = type == '+';
322			}
323		}
324	
325		nick_mode_change(channel, arg, channel->server->modes[umode].prefix,
326				 type, setby);
