337	/* Parse channel mode string */
338	void parse_channel_modes(IRC_CHANNEL_REC *channel, const char *setby,
339				 const char *mode, int update_key)
340	{
341		IRC_SERVER_REC *server = channel->server;
342	        GString *newmode;
343		char *dup, *modestr, *arg, *curmode, type, *old_key;
344		int umode;
345	
346		g_return_if_fail(IS_IRC_CHANNEL(channel));
347		g_return_if_fail(mode != NULL);
348	
349		type = '+';
350		newmode = g_string_new(channel->mode);
351		old_key = update_key ? NULL : g_strdup(channel->key);
352	
353		dup = modestr = g_strdup(mode);
354		curmode = cmd_get_param(&modestr);
355		while (*curmode != '\0') {
356			if (HAS_MODE_ARG(server, type, *curmode)) {
357				/* get the argument for the mode. NOTE: We don't
358				   get the +k's argument when joining to channel. */
359				arg = cmd_get_param(&modestr);
360			} else {
361				arg = NULL;
362			}
363	
364			switch (*curmode) {
365			case '+':
366			case '-':
367				type = *curmode;
368				break;
369			default:
370				umode = (unsigned char) *curmode;
371				if (server->modes[umode].func != NULL) {
372					server->modes[umode].func(channel, setby,
373								  type, *curmode, arg,
374								  newmode);
375				} else {
376					/* Treat unknown modes as ones without params */
377					modes_type_d(channel, setby, type, *curmode,
378						     arg, newmode);
379				}
380			}
381	
382			curmode++;
383		}
384		g_free(dup);
385	
386		if (channel->key != NULL &&
387		    strchr(channel->mode, 'k') == NULL &&
388		    strchr(newmode->str, 'k') == NULL) {
389			/* join was used with key but there's no key set
390			   in channel modes.. */
391			g_free(channel->key);
392			channel->key = NULL;
393		} else if (!update_key && old_key != NULL) {
394			/* get the old one back, just in case it was replaced */
395			g_free(channel->key);
396			channel->key = old_key;
397			mode_set_arg(channel->server, newmode, '+', 'k', old_key, FALSE);
398			old_key = NULL;
399		}
400	
401		if (g_strcmp0(newmode->str, channel->mode) != 0) {
402			g_free(channel->mode);
403			channel->mode = g_strdup(newmode->str);
404	
405			signal_emit("channel mode changed", 2, channel, setby);
406		}
407	
408		g_string_free(newmode, TRUE);
409		g_free(old_key);
410	}
