32	static void check_join_failure(IRC_SERVER_REC *server, const char *channel)
33	{
34		CHANNEL_REC *chanrec;
35		char *chan2;
36	
37		if (channel[0] == '!' && channel[1] == '!')
38			channel++; /* server didn't understand !channels */
39	
40		chanrec = channel_find(SERVER(server), channel);
41		if (chanrec == NULL && channel[0] == '!' && strlen(channel) > 6) {
42			/* it probably replied with the full !channel name,
43			   find the channel with the short name.. */
44			chan2 = g_strdup_printf("!%s", channel+6);
45			chanrec = channel_find(SERVER(server), chan2);
46			g_free(chan2);
47		}
48	
49		if (chanrec != NULL && !chanrec->joined) {
50			chanrec->left = TRUE;
51			channel_destroy(chanrec);
52		}
53	}
54	
55	static void irc_server_event(IRC_SERVER_REC *server, const char *line)
56	{
57		char *params, *numeric, *channel;
58	
59		/* We'll be checking "4xx <your nick> <channel>" for channels
60		   which we haven't joined yet. 4xx are error codes and should
61		   indicate that the join failed. */
62		params = event_get_params(line, 3, &numeric, NULL, &channel);
63	
64		if (numeric[0] == '4')
65			check_join_failure(server, channel);
66	
67		g_free(params);
68	}
69	
70	static void event_no_such_channel(IRC_SERVER_REC *server, const char *data)
71	{
72		CHANNEL_REC *chanrec;
73		CHANNEL_SETUP_REC *setup;
74		char *params, *channel;
75	
76		params = event_get_params(data, 2, NULL, &channel);
77		chanrec = *channel == '!' && channel[1] != '\0' ?
78			channel_find(SERVER(server), channel) : NULL;
79	
80		if (chanrec != NULL) {
81	                /* !channel didn't exist, so join failed */
82			setup = channel_setup_find(chanrec->name,
83						   chanrec->server->connrec->chatnet);
84			if (setup != NULL && setup->autojoin) {
85				/* it's autojoin channel though, so create it */
86				irc_send_cmdv(server, "JOIN !%s", chanrec->name);
87				g_free(params);
88	                        return;
89			}
90		}
91	
92		check_join_failure(server, channel);
93		g_free(params);
94	}
95	
96	static void event_duplicate_channel(IRC_SERVER_REC *server, const char *data)
97	{
98		CHANNEL_REC *chanrec;
99		char *params, *channel, *p;
100	
101		g_return_if_fail(data != NULL);
102	
103		/* this new addition to ircd breaks completely with older
104		   "standards", "nick Duplicate ::!!channel ...." */
105		params = event_get_params(data, 3, NULL, NULL, &channel);
106		p = strchr(channel, ' ');
107		if (p != NULL) *p = '\0';
108	
109		if (channel[0] == '!') {
110			chanrec = channel_find(SERVER(server),
111					       channel+(channel[1] == '!'));
112			if (chanrec != NULL && !chanrec->names_got) {
113				chanrec->left = TRUE;
114				channel_destroy(chanrec);
115			}
116		}
117	
118		g_free(params);
119	}
120	
121	static void channel_change_topic(IRC_SERVER_REC *server, const char *channel,
122					 const char *topic, const char *setby,
123					 time_t settime)
124	{
125		CHANNEL_REC *chanrec;
126		char *recoded = NULL;
127	
128		chanrec = channel_find(SERVER(server), channel);
129		if (chanrec == NULL) return;
130		/* the topic may be send out encoded, so we need to
131		   recode it back or /topic <tab> will not work properly */
132		recoded = recode_in(SERVER(server), topic, channel);
133		if (topic != NULL) {
134			g_free_not_null(chanrec->topic);
135			chanrec->topic = recoded == NULL ? NULL : g_strdup(recoded);
136		}
137		g_free(recoded);
138	
139		g_free_not_null(chanrec->topic_by);
140		chanrec->topic_by = g_strdup(setby);
141	
142		if (chanrec->topic_by == NULL) {
143			/* ensure invariant topic_time > 0 <=> topic_by != NULL.
144			   this could be triggered by a topic command without sender */
145			chanrec->topic_time = 0;
146		} else {
147			chanrec->topic_time = settime;
148		}
149	
150		signal_emit("channel topic changed", 1, chanrec);
151	}
152	
153	static void event_topic_get(IRC_SERVER_REC *server, const char *data)
154	{
155		char *params, *channel, *topic;
156	
157		g_return_if_fail(data != NULL);
158	
159		params = event_get_params(data, 3, NULL, &channel, &topic);
160		channel_change_topic(server, channel, topic, NULL, 0);
161		g_free(params);
162	}
163	
164	static void event_topic(IRC_SERVER_REC *server, const char *data,
165				const char *nick, const char *addr)
166	{
167		char *params, *channel, *topic, *mask;
168	
169		g_return_if_fail(data != NULL);
170	
171		params = event_get_params(data, 2, &channel, &topic);
172		mask = addr == NULL ? g_strdup(nick) :
173			g_strconcat(nick, "!", addr, NULL);
174		channel_change_topic(server, channel, topic, mask, time(NULL));
175		g_free(mask);
176		g_free(params);
177	}
178	
179	static void event_topic_info(IRC_SERVER_REC *server, const char *data)
180	{
181		char *params, *channel, *topicby, *topictime;
182		time_t t;
183	
184		g_return_if_fail(data != NULL);
185	
186		params = event_get_params(data, 4, NULL, &channel,
187					  &topicby, &topictime);
188	
189		t = (time_t) atol(topictime);
190		channel_change_topic(server, channel, NULL, topicby, t);
191		g_free(params);
192	}
193	
194	/* Find any unjoined channel that matches `channel'. Long channel names are
195	   also a bit problematic, so find a channel where start of the name matches. */
196	static IRC_CHANNEL_REC *channel_find_unjoined(IRC_SERVER_REC *server,
197						      const char *channel)
198	{
199		GSList *tmp;
200		int len;
201	
202		len = strlen(channel);
203		for (tmp = server->channels; tmp != NULL; tmp = tmp->next) {
204			IRC_CHANNEL_REC *rec = tmp->data;
205	
206			if (!IS_IRC_CHANNEL(rec) || rec->joined)
207				continue;
208	
209			if (g_ascii_strncasecmp(channel, rec->name, len) == 0 &&
210			    (len > 20 || rec->name[len] == '\0'))
211				return rec;
212		}
213	
214		return NULL;
215	}
216	
217	static void event_join(IRC_SERVER_REC *server, const char *data, const char *nick, const char *address)
218	{
219		char *params, *channel, *tmp, *shortchan;
220		IRC_CHANNEL_REC *chanrec;
221	
222		g_return_if_fail(data != NULL);
223	
224		if (g_ascii_strcasecmp(nick, server->nick) != 0) {
225			/* someone else joined channel, no need to do anything */
226			return;
227		}
228	
229		if (server->userhost == NULL)
230			server->userhost = g_strdup(address);
231	
232		params = event_get_params(data, 1, &channel);
233		tmp = strchr(channel, 7); /* ^G does something weird.. */
234		if (tmp != NULL) *tmp = '\0';
235	
236		if (*channel != '!' || strlen(channel) < 7)
237			shortchan = NULL;
238		else {
239			/* !channels have 5 chars long identification string before
240			   it's name, it's not known when /join is called so rename
241			   !channel here to !ABCDEchannel */
242			shortchan = g_strdup_printf("!%s", channel+6);
243			chanrec = channel_find_unjoined(server, shortchan);
244			if (chanrec != NULL) {
245				channel_change_name(CHANNEL(chanrec), channel);
246				g_free(chanrec->name);
247				chanrec->name = g_strdup(channel);
248			} else {
249				/* well, did we join it with full name? if so, and if
250				   this was the first short one, change it's name. */
251				chanrec = channel_find_unjoined(server, channel);
252				if (chanrec != NULL &&
253				    irc_channel_find(server, shortchan) == NULL) {
254					channel_change_visible_name(CHANNEL(chanrec),
255								    shortchan);
256				}
257			}
258		}
259	
260		chanrec = irc_channel_find(server, channel);
261		if (chanrec != NULL && chanrec->joined) {
262			/* already joined this channel - probably a broken proxy that
263			   forgot to send PART between */
264			chanrec->left = TRUE;
265			channel_destroy(CHANNEL(chanrec));
266			chanrec = NULL;
267		}
268	
269		if (chanrec == NULL) {
270			/* look again, because of the channel name cut issues. */
271			chanrec = channel_find_unjoined(server, channel);
272		}
273	
274		if (chanrec == NULL) {
275			/* didn't get here with /join command.. */
276			chanrec = irc_channel_create(server, channel, shortchan, TRUE);
277		}
278	
279		chanrec->joined = TRUE;
280		if (g_strcmp0(chanrec->name, channel) != 0) {
281	                g_free(chanrec->name);
282			chanrec->name = g_strdup(channel);
283		}
284	
285		g_free(shortchan);
286		g_free(params);
287	}
288	
289	static void event_part(IRC_SERVER_REC *server, const char *data, const char *nick)
290	{
291		char *params, *channel, *reason;
292		CHANNEL_REC *chanrec;
293	
294		g_return_if_fail(data != NULL);
295	
296		if (g_ascii_strcasecmp(nick, server->nick) != 0) {
297			/* someone else part, no need to do anything here */
298			return;
299		}
300	
301		params = event_get_params(data, 2, &channel, &reason);
302	
303		chanrec = channel_find(SERVER(server), channel);
304		if (chanrec != NULL && chanrec->joined) {
305			chanrec->left = TRUE;
306			channel_destroy(chanrec);
307		}
308	
309		g_free(params);
310	}
311	
312	static void event_kick(IRC_SERVER_REC *server, const char *data)
313	{
314		CHANNEL_REC *chanrec;
315		char *params, *channel, *nick, *reason;
316	
317		g_return_if_fail(data != NULL);
318	
319		params = event_get_params(data, 3, &channel, &nick, &reason);
320	
321		if (g_ascii_strcasecmp(nick, server->nick) != 0) {
322			/* someone else was kicked, no need to do anything */
323			g_free(params);
324			return;
325		}
326	
327		chanrec = channel_find(SERVER(server), channel);
328		if (chanrec != NULL) {
329			irc_server_purge_output(server, channel);
330			chanrec->kicked = TRUE;
331			channel_destroy(chanrec);
332		}
333	
334		g_free(params);
335	}
336	
337	static void event_invite(IRC_SERVER_REC *server, const char *data)
338	{
339		char *params, *nick, *channel, *shortchan;
340	
341		g_return_if_fail(data != NULL);
342	
343		params = event_get_params(data, 2, &nick, &channel);
344	
345		if (server->nick_comp_func(nick, server->nick) != 0) {
346			/* someone else was invited, no need to do anything */
347			g_free(params);
348			return;
349		}
350	
351		if (irc_channel_find(server, channel) == NULL) {
352	                /* check if we're supposed to autojoin this channel */
353			CHANNEL_SETUP_REC *setup;
354	
355			setup = channel_setup_find(channel, server->connrec->chatnet);
356			if (setup == NULL && channel[0] == '!' &&
357			    strlen(channel) > 6) {
358				shortchan = g_strdup_printf("!%s", channel+6);
359				setup = channel_setup_find(shortchan,
360							   server->connrec->chatnet);
361				g_free(shortchan);
362			}
363			if (setup != NULL && setup->autojoin && settings_get_bool("join_auto_chans_on_invite"))
364				server->channels_join(SERVER(server), channel, TRUE);
365		}
366	
367		g_free_not_null(server->last_invite);
368		server->last_invite = g_strdup(channel);
369		g_free(params);
370	}
371	
372	void channel_events_init(void)
373	{
374		settings_add_bool("misc", "join_auto_chans_on_invite", TRUE);
375	
376		signal_add_last("server event", (SIGNAL_FUNC) irc_server_event);
377		signal_add_first("event 403", (SIGNAL_FUNC) event_no_such_channel); /* no such channel */
378		signal_add_first("event 407", (SIGNAL_FUNC) event_duplicate_channel); /* duplicate channel */
379	
